import { createRequire } from 'node:module';
import init from '@cossackframework/typescript-plugin';

// tsserver loads the plugin named in compilerOptions.plugins with require().
const require = createRequire(import.meta.url);
if (require('@cossackframework/typescript-plugin') !== init) throw new Error('tsserver must load the plugin factory itself');

// tsserver passes its compiler module and the project's language service.
const typescript = { ScriptElementKind: {}, DiagnosticCategory: { Error: 1, Warning: 0, Suggestion: 2 } };
const calls: string[] = [];
const languageService = {
  getProgram: () => undefined,
  getSemanticDiagnostics: () => { calls.push('semantic'); return []; },
  getSuggestionDiagnostics: () => { calls.push('suggestion'); return []; },
  getCompletionsAtPosition: () => { calls.push('completions'); return undefined; },
  getQuickInfoAtPosition: () => { calls.push('quick-info'); return undefined; },
};
const logs: string[] = [];
const service = init({ typescript }).create({ languageService, project: { projectService: { logger: { info: (line: string) => logs.push(line) } } } });

service.getSemanticDiagnostics('src/view.ts');
service.getSuggestionDiagnostics('src/view.ts');
service.getCompletionsAtPosition('src/view.ts', 0, undefined, undefined);
service.getQuickInfoAtPosition('src/view.ts', 0);
if (calls.join() !== 'semantic,suggestion,completions,quick-info') throw new Error(`Wrapped methods must call the original service: ${calls.join()}`);
if (!logs.some(line => line.includes('template diagnostics and completions enabled'))) throw new Error('The plugin logs when it loads');
